/**
 * R7 decision D7 on the rail, in passkey workspaces on a real local chain (the co-signer's fork with authority "d7",
 * generated by scripts/fork-cosigner.mjs; the budget in rail/authority-ledger.ts):
 *
 *   - after a conversion of 10 tINR, a small payment to the approved payee is still certified and executes (under the
 *     release's C12 it was refused: evidence/20261122-vault-journey.json, step 21); the conversion consumed only its
 *     realised cost against the reference, recomputed here from the chain's own BestExecution event; a payment beyond
 *     the budget is refused before signing with the authority budget named, and the co-signer itself refuses it with
 *     C12 alone, leaving a refusal record whose hash matches; the payment preview equals the co-signer's figures;
 *   - an owner grant signed by the passkey adds to the budget as granted, never as earned; one not signed by a member is
 *     refused; the same signed grant again adds nothing;
 *   - earnings: an escrow job paid to the vault by an outside client adds half its price, only after two
 *     confirmations; the same job funded by the workspace's own owner account, by its agent key or by a second
 *     workspace sharing the member's passkey adds nothing (self-dealt escrow); a workspace sharing no passkey is an
 *     outside client (the rail cannot tell it is not the same person: D7's F1b, stated in the budget's own words);
 *   - conversions: C12 is a conversion's last check; one whose worst case exceeds the budget is refused with C12 named
 *     and nothing is sent; a certificate the co-signer signed and the chain has not used reserves its worst case until
 *     the owner voids it; with the venues' mid pushed outside the fixed reference band, a conversion is refused (fail
 *     closed) where a pool-derived reference would have called it free;
 *   - with authority "release" (QED_RAIL_AUTHORITY=release) a workspace's C12 is the release's again (D-A): after a
 *     conversion above 10 tINR every payment is refused;
 *   - the same over HTTP on the real service with the co-signer in its own process (the default): a grant, a
 *     conversion and a payment, the co-signer's figures in GET /payments/limits, and the same figures after a restart.
 *
 * The escrow's verifier here is a three-byte stub put on the test's own chain with anvil_setCode (PUSH1 32 PUSH1 0
 * RETURN: it accepts every solution). That is the point: the provider chooses the verifier, so "verified" adds meaning,
 * not soundness, and the budget must not rely on it (spec section 3, "What these do not say").
 */
import { after, before, test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, rmSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { encodeFunctionData, getAddress, hashMessage, keccak256, parseEther, toHex, type Address, type Hex } from "viem";
import { generatePrivateKey, privateKeyToAccount } from "viem/accounts";
import { key, startHost, type TestHost } from "./helpers.ts";
import { RP_ID_HASH, SoftwarePasskey, passkeyApproval } from "./passkey.ts";
import { startService, type Service } from "./service-helper.ts";
import { encodeAssertions, toContractAssertion } from "../rail/webauthn.ts";
import { authorityGrantMessage } from "../rail/cosigner.ts";
import type { Rail } from "../rail/host.ts";
import type { Accepted, AuthorityView, Job, PaymentLimits, Proposal } from "../types.ts";

process.env.PATH = `${join(homedir(), ".foundry", "bin")}:${process.env.PATH}`;
const ana = new SoftwarePasskey(), bob = new SoftwarePasskey();
const ACCOUNT_ABI = JSON.parse(readFileSync(join(import.meta.dirname, "..", "accounts", "out", "QEDOwnerAccount.sol", "QEDOwnerAccount.json"), "utf8")).abi;
let h: TestHost, A: Rail;
const view = async (ws: Rail) => (await ws.cosigner.authority()) as AuthorityView;
const step = (j: Job, k: string) => j.steps.find((s) => s.key === k)!;
const checksOf = (j: Job) => (step(j, "cosigner").data as { checks: { id: string; pass: boolean; name: string; detail: string }[] }).checks;
const paise = (x: bigint) => `${x / 100n}.${(x % 100n).toString().padStart(2, "0")}`;
const lo = { n: 4179n, d: 500_000n }; // 84 × (1 − 0.5%) tINR per tUSD, in tINR base units per tUSD base unit
const ceilDiv = (a: bigint, b: bigint) => (a <= 0n ? 0n : (a + b - 1n) / b);

before(async () => {
  h = await startHost("authority", 18763, { heartbeatMs: 3_600_000 });
  A = await h.workspace("ana-home", [ana]);
  for (const [k, p] of [["provision", {}], ["mandate", { maxPerPayment: "2500" }]] as const) assert.equal((await h.act(A, k, p, [ana])).result?.outcome, "executed", k);
});
after(async () => { await h?.stop(); });

test("after a conversion of 10 tINR a payment of 1 tINR to CloudCo is certified and executes; the conversion cost only its realised cost against the reference; a payment and a conversion beyond the budget are refused with C12 named; the preview is the co-signer's figure", async (t) => {
  const v0 = await view(A);
  assert.deepEqual([v0.rule, v0.granted, v0.earned, v0.used, v0.available, v0.asset.symbol], ["d7", "1000", "0", "0", "1000", "tINR"], "10.00 tINR granted at the start (B0, D-A's base), nothing earned or used");
  assert.deepEqual(v0.references.map((r) => [r.symbol, r.lo, r.mid, r.hi]), [["tUSD", "83.58", "84", "84.42"]]);

  const conv = await h.act(A, "convert", { amount: "10" }, [ana]);
  assert.equal(conv.result?.outcome, "executed", conv.error ?? conv.result?.summary);
  const cc = checksOf(conv);
  assert.equal(cc[cc.length - 1].id, "C12", "C12 is the conversion's last check");
  assert.ok(cc.every((c) => c.pass));
  assert.match(cc[cc.length - 1].detail, /cost against the reference/);
  // the realised cost, from the chain's own event: ⌈max(0, spent − out · lo)⌉
  const best = (await A.pub.getContractEvents({ address: A.a.exec, abi: A.v.abi.QEDExecutionAbi, eventName: "BestExecution", fromBlock: BigInt(A.a.deployBlock) })) as { args: { spent: bigint; amountOut: bigint } }[];
  assert.equal(best.length, 1);
  const cost = ceilDiv(best[0].args.spent * lo.d - best[0].args.amountOut * lo.n, lo.d);
  const v1 = await view(A);
  t.diagnostic(`10.00 tINR converted: spent ${best[0].args.spent} paise for ${best[0].args.amountOut} tUSD base units; realised cost against the reference ${paise(cost)} tINR`);
  assert.equal(v1.usedBy.conversions, cost.toString());
  assert.ok(cost > 0n && cost < 20n, `a 10 tINR conversion costs ${paise(cost)} tINR against the reference, not 10 tINR`);
  assert.equal(v1.available, (1000n - cost).toString());

  const pay = await h.act(A, "pay", { payee: "CloudCo", amount: "1" }, [ana]);
  assert.equal(pay.result?.outcome, "executed", pay.error ?? pay.result?.summary);
  const pc = checksOf(pay);
  assert.deepEqual(pc.map((c) => c.id), ["C1", "C2", "C3", "C6", "C9", "C10", "C11", "C12"], "C12 keeps its place among a payment's checks");
  assert.ok(pc.every((c) => c.pass));
  assert.match(pc[7].name, /^Authority budget/);
  assert.match(pc[7].detail, /1\.00 tINR to 0x[0-9a-fA-F]{40}, outside the workspace: it uses 1\.00 tINR/);
  const left = 1000n - cost - 100n;
  const v2 = await view(A);
  assert.deepEqual([v2.usedBy.payments, v2.available], ["100", left.toString()]);

  // the preview is the co-signer's computation: same figure, and the limit to the unit
  const room = (await A.treasury.paymentLimits(paise(left))) as PaymentLimits, over = (await A.treasury.paymentLimits(paise(left + 1n))) as PaymentLimits;
  assert.deepEqual([room.allowed, room.maximum, room.earned.remaining, room.authority?.available], [true, left.toString(), left.toString(), left.toString()]);
  assert.deepEqual([over.allowed, over.checks.filter((c) => !c.pass).map((c) => c.id)], [false, ["authority-budget"]]);
  assert.match(over.checks.find((c) => c.id === "authority-budget")!.rule, /co-signer check C12, R7 decision D7/);

  // a payment beyond the budget: refused before signing, naming the budget; nothing leaves
  const before = (await A.state()).treasury.balance;
  const big = await h.act(A, "pay", { payee: "CloudCo", amount: paise(left + 1n) }, [ana]);
  assert.equal(big.result?.outcome, "refused");
  assert.match(big.result!.summary, /more than is available of the agent's authority budget \(co-signer check C12, R7 D7\)/);
  assert.equal((await A.state()).treasury.balance, before);

  // the co-signer refuses it itself, with C12 alone, and keeps the refusal record
  const am = A.activeMandate()!;
  const p = await A.propose({ kind: "pay", params: { payee: "CloudCo", amount: paise(left + 1n) } });
  const pt = p.terms as any;
  const { signature } = await A.owner.signMessage(pt, passkeyApproval(p, [ana], A.now()), { notBeforeMs: Date.parse(p.createdAt), notAfterMs: Date.parse(p.expiresAt), nowMs: A.now() });
  const r = await A.cosigner.evaluatePayment({ kind: "owner-instructed", mandate: am.mandate, ownerSig: am.ownerSig, payee: pt.payee, amount: BigInt(pt.amountRaw), instruction: pt.instruction, nonce: pt.nonce, instructionSig: signature });
  assert.deepEqual([r.approved, r.checks.filter((c: any) => !c.pass).map((c: any) => c.id), r.certificate], [false, ["C12"], undefined]);
  const file = JSON.parse(readFileSync(r.recordPath, "utf8"));
  assert.deepEqual([file.core.verdict, keccak256(toHex(file.canonical)), file.evidenceHash], ["REFUSED", r.evidenceHash, r.evidenceHash]);
  assert.equal(file.core.checks.find((c: any) => c.id === "C12").pass, false);
  A.cancelProposal(p.id);

  // a conversion whose worst case (the order's floor at the band's low end: about 1.8% of 1,000 tINR) is beyond what is available
  const reserve0 = (await A.state()).reserve.balance;
  const conv2 = await h.act(A, "convert", { amount: "1000" }, [ana]);
  assert.equal(conv2.result?.outcome, "refused", conv2.result?.summary);
  const bc = checksOf(conv2);
  assert.deepEqual(bc.filter((c) => !c.pass).map((c) => c.id), ["C12"], "only C12: every other check passes");
  assert.match(bc.find((c) => c.id === "C12")!.detail, /it can cost at most [\d.]+ tINR/);
  t.diagnostic(`1,000.00 tINR conversion refused: worst case ${/it can cost at most ([\d.]+) tINR/.exec(bc.find((c) => c.id === "C12")!.detail)![1]} tINR, available ${paise(left)} tINR`);
  assert.equal((await A.state()).reserve.balance, reserve0, "nothing was sent");
  assert.equal((await view(A)).available, left.toString(), "a refusal reserves nothing");
});

test("an owner grant signed by the passkey adds to the budget as granted, never as earned; a grant not signed by a member is refused; the same grant again adds nothing", async () => {
  const v0 = await view(A);
  const g = await h.act(A, "grant", { amount: "50" }, [ana]);
  assert.equal(g.result?.outcome, "executed", g.error ?? g.result?.summary);
  assert.equal(g.result?.tx, undefined, "a grant sends no transaction");
  const v1 = await view(A);
  assert.deepEqual([v1.grants, v1.granted, v1.earned, BigInt(v1.available) - BigInt(v0.available)], ["5000", "6000", v0.earned, 5000n]);
  // a grant signed by someone who is not a signer of the owner account
  const msg = authorityGrantMessage(A.a.vault, 1_000_000n, `forged-${key()}`);
  const hash = (await A.read(A.a.ownerAccount!, ACCOUNT_ABI, "replaySafeHash", [hashMessage(msg)])) as Hex;
  await assert.rejects(() => A.cosigner.registerGrant(msg, encodeAssertions([toContractAssertion(bob.assert(hash))])), /not signed by the vault owner/);
  // an ordinary key cannot sign for the passkey account either
  const byAgent = await A.K.OPERATOR.signMessage({ message: msg });
  await assert.rejects(() => A.cosigner.registerGrant(msg, byAgent), /not signed by the vault owner/);
  // the job's own signed grant, registered again (a retry): nothing more
  const rec = A.decisions(20).find((d) => d.kind === "owner-grant")!.record as { message: string };
  const again = await A.cosigner.registerGrant(rec.message, "0x" as Hex);
  assert.deepEqual([again.duplicate, again.granted], [true, "5000"]);
  assert.equal((await view(A)).grants, "5000");
  // the baseline's rule has no grants; nor does a workspace whose co-signer applies the release's rule (see the last test)
});

/** The owner account of `ws` runs `calls` with one member's passkey (as the wallet would, through its execute digest). */
async function accountRuns(ws: Rail, signer: SoftwarePasskey, calls: { target: Address; data: Hex }[]) {
  const acct = ws.a.ownerAccount!, bare = calls.map((c) => ({ target: getAddress(c.target), value: 0n, data: c.data }));
  const nonce = (await ws.read(acct, ACCOUNT_ABI, "nonce")) as bigint, deadline = BigInt(Math.floor(ws.now() / 1000) + 600);
  const digest = (await ws.read(acct, ACCOUNT_ABI, "executeDigest", [bare, nonce, deadline])) as Hex;
  return ws.c.send(ws.relayer!, acct, encodeFunctionData({ abi: ACCOUNT_ABI, functionName: "execute", args: [bare, nonce, deadline, [toContractAssertion(signer.assert(digest))]] }));
}

test("earnings: a job paid to the vault by an outside client adds half its price after two confirmations; paid by the workspace's own account, its agent key or a workspace sharing the passkey it adds nothing; a workspace sharing no passkey is an outside client", async () => {
  const V = A.v, fn = V.chain.fn, escrow = h.host.market!.escrow, inr = A.a.asset!;
  // a second workspace of the same member (her passkey), and one of someone else
  const L = await h.workspace("ana-shop", [ana]), U = await h.workspace("bob-home", [bob]);
  for (const [ws, k] of [[L, ana], [U, bob]] as const) assert.equal((await h.act(ws, "provision", {}, [k])).result?.outcome, "executed");
  const verifier = getAddress(`0x${"7e".repeat(20)}`);
  await A.rpc("anvil_setCode", [verifier, "0x60206000f3"]);
  const provider = privateKeyToAccount(generatePrivateKey());
  await A.rpc("anvil_setBalance", [provider.address, toHex(parseEther("1"))]);
  let q = 0;
  /** A provider-signed quote paying A's vault, funded by `pay(quote, sig)`, then delivered: returns the job id. */
  const job = async (price: bigint, fund: (quote: any, sig: Hex) => Promise<unknown>) => {
    const now = await A.chainNow();
    const spec = toHex(`authority-rail job ${++q}`);
    const quote = { provider: provider.address, payee: A.a.vault, client: "0x0000000000000000000000000000000000000000", token: inr, price, verifier, specHash: keccak256(spec), deliverBy: now + 3600n, validUntil: now + 1800n, quoteId: keccak256(toHex(`quote-${q}`)) };
    await fund(quote, await V.eip712.signQuote(provider, 31337, escrow, quote as never));
    const id = (await A.read(escrow, V.abi.ProofEscrowAbi, "jobCount")) as bigint;
    await A.c.send(provider, escrow, fn(V.abi.ProofEscrowAbi, "deliver", [id, spec, "0x01"]));
    return id;
  };
  const byKey = async (who: any, price: bigint) => job(price, async (quote, sig) => {
    await A.rpc("anvil_setBalance", [who.address, toHex(parseEther("1"))]);
    await A.c.send(A.K.LP1, inr, fn(V.abi.TestTokenAbi, "mint", [who.address, price])); // the host's deployer mints test tokens
    await A.c.send(who, inr, fn(V.abi.TestTokenAbi, "approve", [escrow, price]));
    await A.c.send(who, escrow, fn(V.abi.ProofEscrowAbi, "open", [quote, sig]));
  });
  const byAccount = async (ws: Rail, signer: SoftwarePasskey, price: bigint) => job(price, (quote, sig) => accountRuns(ws, signer, [
    { target: inr, data: encodeFunctionData({ abi: V.abi.TestTokenAbi, functionName: "approve", args: [escrow, price] }) },
    { target: escrow, data: encodeFunctionData({ abi: V.abi.ProofEscrowAbi, functionName: "open", args: [quote, sig] }) },
  ]));
  const v0 = await view(A);
  // self-dealt: the workspace's own owner account, its agent key, the same member's second workspace
  await byAccount(A, ana, 40_000n);
  await byKey(A.K.OPERATOR, 40_000n);
  await byAccount(L, ana, 40_000n);
  const v1 = await view(A);
  assert.deepEqual([v1.earned, v1.notEarnings, v1.available], [v0.earned, 3, v0.available], "400.00 tINR paid in three times: nothing earned");
  // an outside client: credited only after two confirmations
  const client = privateKeyToAccount(generatePrivateKey());
  await byKey(client, 20_001n);
  const v2 = await view(A);
  assert.deepEqual([v2.earned, v2.pendingCredits], [v0.earned, 1], "settled in the latest block: one confirmation, not yet earnings");
  await A.rpc("evm_mine");
  const v3 = await view(A);
  assert.deepEqual([v3.earned, v3.pendingCredits, BigInt(v3.available) - BigInt(v0.available)], [(BigInt(v0.earned) + 10_000n).toString(), 0, 10_000n], "⌊½ · 200.01⌋ = 100.00 tINR");
  // a workspace that shares no passkey with A is an outside client to it: the rail cannot tell who is behind it (F1b)
  await byAccount(U, bob, 10_000n);
  await A.rpc("evm_mine");
  const v4 = await view(A);
  assert.equal(BigInt(v4.earned) - BigInt(v3.earned), 5_000n);
  assert.match(v4.limits[0], /cannot be told apart from an unregistered address of a member/);
  assert.equal(v4.granted, v3.granted, "earnings are never reported as granted");
});

test("conversions: a certificate the chain has not used reserves its worst case until the owner voids it; a market pushed outside the fixed reference is refused, not called free", async (tc) => {
  const v0 = await view(A);

  // a certificate the co-signer signs and nobody sends: its worst case is reserved
  const am = A.activeMandate()!;
  const p = await A.propose({ kind: "convert", params: { amount: "100" } });
  const t = p.terms as any;
  const { signature } = await A.owner.signMessage(t, passkeyApproval(p, [ana], A.now()), { notBeforeMs: Date.parse(p.createdAt), notAfterMs: Date.parse(p.expiresAt), nowMs: A.now() });
  const cert = await A.cosigner.evaluateTrade({ mandate: am.mandate, ownerSig: am.ownerSig, module: A.a.exec, tokenIn: A.a.asset, tokenOut: A.a.reserveAsset, recipient: A.a.reserve, amountIn: BigInt(t.amountIn), instruction: t.instruction, nonce: t.nonce, instructionSig: signature, brainEngine: "test" });
  assert.equal(cert.approved, true, cert.reasons?.join("; "));
  const worst = BigInt(/it can cost at most ([\d.]+) tINR/.exec(cert.checks.find((c: any) => c.id === "C12").detail)![1].replace(".", ""));
  const v1 = await view(A);
  tc.diagnostic(`a 100.00 tINR conversion certified and not sent: worst case ${paise(worst)} tINR reserved`);
  assert.deepEqual([v1.reserved, BigInt(v0.available) - BigInt(v1.available)], [worst.toString(), worst]);
  // two payment certificates asked for at once, each fitting alone and not both: exactly one is signed (the co-signer
  // admits them one at a time and the first one's reservation counts against the second)
  const each = (BigInt(v1.available) * 6n) / 10n;
  const asked = [];
  for (let i = 0; i < 2; i++) {
    const pp = await A.propose({ kind: "pay", params: { payee: "CloudCo", amount: paise(each) } });
    const tt = pp.terms as any;
    const { signature: s } = await A.owner.signMessage(tt, passkeyApproval(pp, [ana], A.now()), { notBeforeMs: Date.parse(pp.createdAt), notAfterMs: Date.parse(pp.expiresAt), nowMs: A.now() });
    asked.push({ kind: "owner-instructed", mandate: am.mandate, ownerSig: am.ownerSig, payee: tt.payee, amount: BigInt(tt.amountRaw), instruction: tt.instruction, nonce: tt.nonce, instructionSig: s });
  }
  const both = await Promise.all(asked.map((x) => A.cosigner.evaluatePayment(x)));
  assert.deepEqual(both.map((x) => x.approved).sort(), [false, true], "exactly one of the two is certified");
  assert.deepEqual(both.find((x) => !x.approved)!.checks.filter((c: any) => !c.pass).map((c: any) => c.id), ["C12"]);
  assert.equal((await view(A)).reserved, (worst + each).toString(), "the conversion's worst case and the certified payment are both reserved");
  // the owner voids every certificate (the vault's epoch moves on): nothing is reserved any more
  assert.equal((await h.act(A, "void-all", {}, [ana])).result?.outcome, "executed");
  assert.deepEqual([(await view(A)).reserved, (await view(A)).available], ["0", v0.available]);
  assert.equal((await h.act(A, "mandate", { maxPerPayment: "2500" }, [ana])).result?.outcome, "executed");

  // someone adds 5% more tUSD to every direct tINR/tUSD venue and 5% more tEUR to the tINR/tEUR one (anyone holding test
  // tokens could: TestUSD has a public faucet), so both routes now price tUSD at about 80 tINR, below the reference
  // band's 83.58, with no arbitrage between them for the release's solver to trip on. Against a band read from the
  // pools that would be the truth; against the fixed band a conversion would look free (its cost floored at zero).
  const m = h.host.market!, V = A.v, fn = V.chain.fn;
  for (const [i, token, abi] of [[0, m.usd, V.abi.TestUSDAbi], [1, m.usd, V.abi.TestUSDAbi], [4, m.usd, V.abi.TestUSDAbi], [2, m.eur, V.abi.TestTokenAbi]] as const) {
    const pool = m.inrPools[i];
    const [r0, r1] = (await A.read(pool, V.abi.CPMMPoolAbi, "getReserves")) as [bigint, bigint, number];
    const is0 = getAddress((await A.read(pool, V.abi.CPMMPoolAbi, "token0")) as Address) === getAddress(token);
    await A.c.send(A.K.LP1, token, fn(abi as never, "mint", [pool, (is0 ? r0 : r1) / 20n]));
    await A.c.send(A.K.LP1, pool, fn(V.abi.CPMMPoolAbi, "sync"));
  }
  const pushed = await h.act(A, "convert", { amount: "10" }, [ana]);
  assert.equal(pushed.result?.outcome, "refused", pushed.result?.summary);
  const pk = checksOf(pushed);
  assert.deepEqual(pk.filter((c) => !c.pass).map((c) => c.id), ["C12"], `only C12: the release's own screens pass. ${JSON.stringify(pk.filter((c) => !c.pass).map((c) => [c.id, c.detail]))}`);
  assert.match(pk.find((c) => c.id === "C12")!.detail, /outside the reference band 83\.58 to 84\.42 tINR per tUSD .*: the reference does not describe the market now/);
});

test("with authority \"release\" a workspace's C12 is the release's (D-A): after a conversion above 10 tINR every payment is refused, as on 22 Nov", async () => {
  const t = await startHost("authority-release", 18765, { heartbeatMs: 3_600_000, authority: "release" });
  try {
    const cara = new SoftwarePasskey();
    const R = await t.workspace("cara-home", [cara]);
    for (const [k, p] of [["provision", {}], ["mandate", { maxPerPayment: "2500" }]] as const) assert.equal((await t.act(R, k, p, [cara])).result?.outcome, "executed", k);
    assert.deepEqual(await R.cosigner.authority(), { rule: "release" });
    await assert.rejects(() => R.propose({ kind: "grant", params: { amount: "5" } }), (e: { code?: string }) => e.code === "authority_release_rule");
    assert.equal((await t.act(R, "convert", { amount: "10.01" }, [cara])).result?.outcome, "executed");
    const limits = (await R.treasury.paymentLimits(null)) as PaymentLimits;
    assert.deepEqual([limits.maximum, limits.earned.remaining, limits.authority], ["0", "0", undefined]);
    const pay = await t.act(R, "pay", { payee: "CloudCo", amount: "0.01" }, [cara]);
    assert.equal(pay.result?.outcome, "refused");
    assert.match(pay.result!.summary, /co-signer's earned allowance/);
  } finally { await t.stop(); }
});

// ───────────── the same through the real service, with the co-signer in its own process (the default) ─────────────

async function httpAct(s: Service, ws: string, kind: string, params: Record<string, unknown>, signers: SoftwarePasskey[]): Promise<Job> {
  const p = await s.call<Proposal>("POST", `/workspaces/${ws}/proposals`, { kind, params });
  assert.equal(p.status, 201, JSON.stringify(p.data));
  const a = await s.call<Accepted>("POST", `/workspaces/${ws}/proposals/${p.data.id}/execute`, { approval: passkeyApproval(p.data, signers) }, { "Idempotency-Key": key() });
  assert.equal(a.status, 202, JSON.stringify(a.data));
  for (let i = 0; i < 600; i++) {
    const j = (await s.call<Job>("GET", `/workspaces/${ws}/jobs/${a.data.jobId}`)).data;
    if (["done", "failed", "interrupted"].includes(j.status)) return j;
    await new Promise((r) => setTimeout(r, 100));
  }
  throw new Error("job did not finish");
}

test("over HTTP with the co-signer in its own process: a grant, a conversion and a payment; GET /payments/limits carries the co-signer's figures, and the same figures after a restart of the service", { timeout: 240_000 }, async () => {
  const env = { QED_RAIL_MODE: "multi-tenant", QED_RAIL_ACCOUNT_DELAY_S: "60", QED_RAIL_ACCOUNT_RECOVERY_DELAY_S: "60" };
  const s = await startService("svc-authority", 15193, 18767, { env, workspace: null });
  const dina = new SoftwarePasskey();
  const dir = s.dir;
  let stopped = false;
  try {
    assert.equal((await s.call("POST", "/workspaces", { workspaceId: "dina-home", owner: dina.publicKey, rpIdHash: RP_ID_HASH })).status, 201);
    for (const [k, p] of [["provision", {}], ["mandate", { maxPerPayment: "2500" }], ["grant", { amount: "25.5" }], ["convert", { amount: "10" }], ["pay", { payee: "CloudCo", amount: "2" }]] as const) {
      const j = await httpAct(s, "dina-home", k, p, [dina]);
      assert.equal(j.result?.outcome, "executed", `${k}: ${j.error ?? j.result?.summary}`);
    }
    const st = (await s.call("GET", "/workspaces/dina-home/state")).data;
    assert.equal(st.roles.cosignerIsolation, "separate-process");
    const lim = (await s.call<PaymentLimits>("GET", "/workspaces/dina-home/payments/limits")).data;
    const a = lim.authority!;
    assert.deepEqual([a.rule, a.base, a.grants, a.granted, a.earned, a.usedBy.payments], ["d7", "1000", "2550", "3550", "0", "200"]);
    assert.ok(BigInt(a.usedBy.conversions) > 0n && BigInt(a.usedBy.conversions) < 20n, a.statement);
    assert.equal(BigInt(a.available), 3550n - 200n - BigInt(a.usedBy.conversions));
    assert.deepEqual([lim.earned.remaining, lim.maximum], [a.available, a.available]);
    assert.match(a.statement, /^\d+\.\d{2} tINR available = granted 35\.50 \(base 10\.00, owner grants 25\.50\) \+ earned 0\.00 − used/);
    assert.equal(await s.stop(), 0);
    stopped = true;
    const s2 = await startService("svc-authority", 15193, 18767, { env, workspace: null, dir });
    try {
      const again = (await s2.call<PaymentLimits>("GET", "/workspaces/dina-home/payments/limits")).data.authority!;
      assert.deepEqual({ ...again, pendingCredits: 0 }, { ...a, pendingCredits: 0 }, "the co-signer's grants and the chain's history give the same budget after a restart");
    } finally { await s2.stop(); }
  } finally { if (!stopped) await s.stop(); rmSync(dir, { recursive: true, force: true }); }
});
